// Banach-Tarski on the GPU (maths in gallery-banach-model.js; stage in gl3d.js). The orbit of a point p of the sphere under the free
// group generated by two rotations by arccos(1/3) is drawn as lit spheres (one instance per reduced word, up to 118,097), coloured by
// the piece of the word: S(a), S(A), S(b), S(B) and {e}. The rotations of the words live in a GPU buffer, so dragging p moves the whole
// orbit in one uniform. "Play" turns S(A) by a and S(B) by b, then pulls the two copies apart: each copy lands exactly on the orbit
// again (every word of length ≤ n - 1). The tree below shows the same pieces in the Cayley graph of F₂.
import { glStage, glExhibit, compile, vao, gridMesh, raySphere, rgb, GLSL_LIGHT, clamp, norm3 } from './gl3d.js';
import { freeGroup, distinctRotations, copies, words, pieceSize, axisRotation, AXIS, THETA, LETTERS } from './gallery-banach-model.js';
import { canvasIn, field as sliderField, bind } from '../object-kit.js';
import { metricStrip } from './gallery-panels.js';

const PIECES = ['e', 'a', 'A', 'b', 'B'];
const POINT_VS = `#version 300 es
precision highp float;
in vec3 aR0; in vec3 aR1; in vec3 aR2; in vec2 aInfo;
uniform mat4 uVP; uniform vec3 uRight, uUp, uP; uniform mat3 uRot[5]; uniform vec3 uOff[5]; uniform vec3 uCol[5];
uniform float uSize, uDecay, uFade[5];
out vec2 vC; out vec3 vCol; out float vFade;
void main(){
  int k = gl_VertexID; vec2 c = vec2(k == 1 || k == 3 ? 1.0 : -1.0, k >= 2 ? 1.0 : -1.0);
  int pi = int(aInfo.x + 0.5);
  vec3 q = vec3(dot(aR0, uP), dot(aR1, uP), dot(aR2, uP));
  vec3 w = uOff[pi] + uRot[pi] * q;
  float r = uSize * pow(uDecay, aInfo.y);
  gl_Position = uVP * vec4(w + (uRight * c.x + uUp * c.y) * r, 1.0);
  vC = c; vCol = uCol[pi]; vFade = uFade[pi];
}`;
const POINT_FS = `#version 300 es
precision highp float; precision highp int;
in vec2 vC; in vec3 vCol; in float vFade; out vec4 frag;
${GLSL_LIGHT}
void main(){
  float d = dot(vC, vC); if (d > 1.0 || vFade < 0.01) discard;
  vec3 n = vec3(vC.x, vC.y, sqrt(1.0 - d));
  vec3 col = studio(vCol, vec3(n.x, n.z, n.y), vec3(0.0, 1.0, 0.0), 50.0, 0.35);
  frag = vec4(toSRGB(col), 1.0);
}`;
const SHELL_VS = `#version 300 es
precision highp float;
in vec2 aUV; uniform mat4 uVP; uniform vec3 uCentre; out vec3 vN; out vec3 vW;
void main(){ float th = aUV.x * 6.283185307179586, ph = (aUV.y - 0.5) * 3.141592653589793;
  vN = vec3(cos(ph) * cos(th), cos(ph) * sin(th), sin(ph)); vW = uCentre + vN; gl_Position = uVP * vec4(vW, 1.0); }`;
const SHELL_FS = `#version 300 es
precision highp float; precision highp int;
in vec3 vN; in vec3 vW; uniform vec3 uEye, uTint; uniform float uAlpha; out vec4 frag;
void main(){
  vec3 n = normalize(vN), V = normalize(uEye - vW); float f = pow(1.0 - abs(dot(n, V)), 2.5);
  float lat = abs(fract(atan(n.y, n.x) / 0.5235987755982988 + 0.5) - 0.5), lon = abs(fract(asin(clamp(n.z, -1.0, 1.0)) / 0.5235987755982988 + 0.5) - 0.5);
  float grid = max(1.0 - smoothstep(0.0, fwidth(lat) * 1.5, lat), 1.0 - smoothstep(0.0, fwidth(lon) * 1.5, lon));
  float a = uAlpha * (0.05 + 0.55 * f + 0.10 * grid);
  frag = vec4(pow(uTint, vec3(1.0 / 2.2)) * a, a);
}`;
const I3 = [1, 0, 0, 0, 1, 0, 0, 0, 1];
const colMajor3 = (m) => [m[0], m[3], m[6], m[1], m[4], m[7], m[2], m[5], m[8]];
const ease = (x) => { x = clamp(x, 0, 1); return x * x * (3 - 2 * x); };

export function banachTarski(root, opts) {
  const { t, lang } = opts, reduced = typeof opts.reduced === 'function' ? opts.reduced : () => !!opts.reduced;
  const coarse = globalThis.matchMedia?.('(pointer: coarse)').matches, maxN = coarse ? 8 : 10;
  const int = (v) => Number(v).toLocaleString(lang), pct = (v) => (100 * v).toLocaleString(lang, { maximumFractionDigits: 1, minimumFractionDigits: 1 }) + ' %';
  const st = { n: Math.min(7, maxN), time: 0, playing: false, p: norm3([0.42, -0.58, 0.69]), orbits: 1, size: 1 };
  const page = glExhibit(root, opts,
    t('Chaque bille est l’image du point p par une rotation du groupe engendré par a et b (deux rotations d’angle arccos(1/3)). Sa couleur dit par quelle lettre commence le mot : les cinq pièces. Glisse le point p (la grosse bille noire) sur la sphère, puis lance la lecture : deux pièces tournent, et chaque paire redonne toute l’orbite.',
      'Each bead is the image of the point p by a rotation of the group generated by a and b (two rotations by arccos(1/3)). Its colour says which letter starts the word: the five pieces. Drag the point p (the big dark bead) on the sphere, then press play: two pieces turn, and each pair gives back the whole orbit.'),
    `<div class="act-buttons"><button type="button" class="btn btn-primary" id="bt-play">${t('Lecture', 'Play')}</button><button type="button" class="btn btn-secondary" id="bt-reset">${t('Recommencer', 'Restart')}</button></div>` +
    sliderField('bt-time', t('Étape : 0 départ, 1 deux pièces tournées, 2 deux boules', 'Step: 0 start, 1 two pieces turned, 2 two balls'), 0, 2, 0.001, 0) +
    sliderField('bt-n', t('Longueur maximale des mots n', 'Maximum word length n'), 1, maxN, 1, st.n) +
    sliderField('bt-orbits', t('Nombre d’orbites dessinées', 'Number of orbits drawn'), 1, 4, 1, 1) +
    sliderField('bt-size', t('Taille des billes', 'Bead size'), 0.4, 2, 0.05, 1),
    `<p>${t('Les rotations a (axe vertical) et b (axe horizontal) d’angle θ = arccos(1/3) engendrent un groupe libre : deux mots réduits différents donnent deux rotations différentes. Ici, ce fait est vérifié sans arrondi pour tous les mots de longueur au plus n : multipliées par 3ᵏ, les matrices ont des coefficients x + y√2 avec x et y entiers, calculés exactement.', 'The rotations a (vertical axis) and b (horizontal axis) by θ = arccos(1/3) generate a free group: two different reduced words give two different rotations. Here this is checked with no rounding for every word of length at most n: multiplied by 3ᵏ, the matrices have entries x + y√2 with integers x and y, computed exactly.')}</p>` +
    `<p>${t('Les mots se répartissent en {e}, S(a), S(A), S(b), S(B) (A = a⁻¹, B = b⁻¹). Or a·S(A) est l’ensemble des mots qui ne commencent pas par a : S(a) et a·S(A) redonnent tout le groupe, et de même S(b) et b·S(B). En comptant les mots, S(A) en contient un quart, a·S(A) trois quarts : aucun « volume » additif et invariant par rotation ne peut être donné à ces pièces.', 'The words split into {e}, S(a), S(A), S(b), S(B) (A = a⁻¹, B = b⁻¹). Now a·S(A) is the set of words that do not start with a: S(a) and a·S(A) give back the whole group, and so do S(b) and b·S(B). Counting words, S(A) holds a quarter of them and a·S(A) three quarters: no additive “volume” that rotations preserve can be given to these pieces.')}</p>` +
    `<p>${t('Pour la boule entière, on fait de même dans chaque orbite. Il faut alors choisir un point de départ dans chacune des orbites, en nombre non dénombrable, sans règle pour le faire : c’est l’axiome du choix. Les pièces obtenues ne sont pas mesurables. Le dessin est fini et honnête : il montre les mots jusqu’à la longueur n, et chaque copie couvre exactement les mots de longueur au plus n − 1 ; le paradoxe n’existe qu’à l’infini. Les points des axes et le centre demandent un ajustement supplémentaire, omis ici.', 'For the whole ball, the same is done in every orbit. One must then choose a starting point in each of the uncountably many orbits, with no rule to do it: this is the axiom of choice. The pieces obtained are not measurable. The drawing is finite and honest: it shows the words up to length n, and each copy covers exactly the words of length at most n − 1; the paradox only exists in the infinite. The points on the axes and the centre need an extra adjustment, left out here.')}</p>`);
  const stage = glStage(page.host, { aspect: 640 / 420, label: t('Orbite d’un point sous le groupe libre, en 3D. Flèches pour tourner, + et − pour zoomer, 0 pour revenir.', 'Orbit of a point under the free group, in 3D. Arrows turn it, + and − zoom, 0 resets.'), view: { yaw: 0.38, pitch: 0.26, dist: 6.2, fov: 0.55 }, minDist: 2, maxDist: 16, reduced, scope: root });
  if (!stage) return null;
  const gl = stage.gl, $ = (s) => root.querySelector(s);
  const metrics = metricStrip(page.host, t, [
    { id: 'words', label: t('Mots de longueur ≤ n', 'Words of length ≤ n'), kind: 'exact' },
    { id: 'piece', label: t('Mots dans chaque pièce', 'Words in each piece'), kind: 'exact' },
    { id: 'distinct', label: t('Rotations distinctes (calcul exact)', 'Distinct rotations (exact check)'), kind: 'exact' },
    { id: 'quarter', label: t('S(A) parmi les mots ≤ n', 'S(A) among words ≤ n'), kind: 'exact' },
    { id: 'three', label: t('a·S(A) parmi les mots ≤ n − 1', 'a·S(A) among words ≤ n − 1'), kind: 'exact' },
    { id: 'cover', label: t('Chaque copie couvre les mots ≤ n − 1', 'Each copy covers the words ≤ n − 1'), kind: 'exact' },
  ]);
  // Cayley tree panel
  const fig = root.ownerDocument.createElement('figure'); fig.className = 'exhibit-plot'; const treeHost = root.ownerDocument.createElement('div'); fig.append(treeHost);
  const cap = root.ownerDocument.createElement('figcaption'); fig.append(cap); metrics.el.after(fig);
  const tree = canvasIn(treeHost, 640 / 230, { navigation: false }); tree.cv.setAttribute('role', 'img');
  // ---- GPU
  let P, pts = null, shell, G = null, exactJob = 0;
  function build() {
    P = { pt: compile(gl, POINT_VS, POINT_FS), shell: compile(gl, SHELL_VS, SHELL_FS) };
    const g = gridMesh(128, 64); shell = vao(gl, P.shell, { aUV: { data: g.uv, size: 2 } }, g.idx);
    upload();
  }
  function upload() {
    G = freeGroup(st.n, { exact: false });
    const N = G.list.length, r0 = new Float32Array(N * 3), r1 = new Float32Array(N * 3), r2 = new Float32Array(N * 3), info = new Float32Array(N * 2);
    G.list.forEach((x, i) => { const m = G.float.subarray(i * 9, i * 9 + 9); r0.set(m.subarray(0, 3), i * 3); r1.set(m.subarray(3, 6), i * 3); r2.set(m.subarray(6, 9), i * 3); info[i * 2] = PIECES.indexOf(x.first || 'e'); info[i * 2 + 1] = x.len; });
    if (pts) gl.deleteVertexArray(pts.vao);
    pts = vao(gl, P.pt, { aR0: { data: r0, size: 3, divisor: 1 }, aR1: { data: r1, size: 3, divisor: 1 }, aR2: { data: r2, size: 3, divisor: 1 }, aInfo: { data: info, size: 2, divisor: 1 } });
    pts.count = N; report(null); stage.wake();
    clearTimeout(exactJob);
    exactJob = setTimeout(() => { const E = freeGroup(st.n); report({ distinct: distinctRotations(E), ...copies(E) }); }, 30);
  }
  function report(check) {
    const n = st.n, W = words(n), S = pieceSize(n), Wm = words(n - 1), aSA = Wm - pieceSize(n - 1);
    metrics.set('words', `2·3${sup(n)} − 1 = ${int(W)}`); metrics.set('piece', `(3${sup(n)} − 1)/2 = ${int(S)}`);
    metrics.set('quarter', pct(S / W)); metrics.set('three', n > 1 ? pct(aSA / Wm) : '–');
    metrics.set('distinct', check ? `${int(check.distinct)} / ${int(W)}` : t('vérification…', 'checking…'));
    metrics.set('cover', check ? (check.oneCovers && check.twoCovers ? t('oui (vérifié)', 'yes (checked)') : t('non', 'no')) : '…');
    page.read(t(`${int(W)} billes par orbite ; S(a) et a·S(A) redonnent l’orbite, S(b) et b·S(B) aussi.`, `${int(W)} beads per orbit; S(a) and a·S(A) give back the orbit, and so do S(b) and b·S(B).`));
  }
  const sup = (n) => String(n).split('').map((d) => '⁰¹²³⁴⁵⁶⁷⁸⁹'[d]).join('');
  // extra orbits: fixed generic points
  const EXTRA = [[0.83, 0.31, -0.46], [-0.27, 0.92, 0.28], [-0.61, -0.44, -0.66]].map(norm3);
  function poses() {
    const r = ease(st.time), s = ease(st.time - 1), sep = 1.25 * s;
    const rot = { e: I3, a: I3, b: I3, A: axisRotation(AXIS.a, r * THETA), B: axisRotation(AXIS.b, r * THETA) };
    const off = { e: [0, 0, -2.3 * s], a: [0, -sep, 0], A: [0, -sep, 0], b: [0, sep, 0], B: [0, sep, 0] };
    return { rot, off, s };
  }
  stage.draw = (f) => {
    const C = f.C, VP = new Float32Array(f.viewProj), v = f.view, right = [v[0], v[4], v[8]], up = [v[1], v[5], v[9]];
    const { rot, off, s } = poses(), cols = { e: rgb(C.ink), a: rgb(C.c[0]), A: rgb(C.c[1]), b: rgb(C.c[2]), B: rgb(C.c[3]) };
    gl.useProgram(P.pt);
    gl.uniformMatrix4fv(P.pt.u('uVP'), false, VP); gl.uniform3fv(P.pt.u('uRight'), right); gl.uniform3fv(P.pt.u('uUp'), up);
    gl.uniformMatrix3fv(P.pt.u('uRot'), false, new Float32Array(PIECES.flatMap((k) => colMajor3(rot[k]))));
    gl.uniform3fv(P.pt.u('uOff'), new Float32Array(PIECES.flatMap((k) => off[k]))); gl.uniform3fv(P.pt.u('uCol'), new Float32Array(PIECES.flatMap((k) => cols[k])));
    gl.uniform1fv(P.pt.u('uFade'), new Float32Array([1, 1, 1, 1, 1]));
    gl.uniform1f(P.pt.u('uDecay'), 0.8);
    gl.bindVertexArray(pts.vao);
    [st.p, ...EXTRA.slice(0, st.orbits - 1)].forEach((p, i) => {
      gl.uniform3fv(P.pt.u('uP'), p); gl.uniform1f(P.pt.u('uSize'), 0.075 * st.size * (i ? 0.8 : 1));
      gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, pts.count);
    });
    // the seed p, large
    gl.bindVertexArray(null);
    // glass shells: the ball, then the two copies
    gl.useProgram(P.shell); gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA); gl.depthMask(false);
    gl.uniformMatrix4fv(P.shell.u('uVP'), false, VP); gl.uniform3fv(P.shell.u('uEye'), f.eye); gl.uniform3fv(P.shell.u('uTint'), rgb(C.ink));
    gl.bindVertexArray(shell.vao);
    const shells = s < 0.002 ? [[[0, 0, 0], 1]] : [[[0, 0, 0], 1 - s], [off.a, s], [off.b, s]];
    for (const [c, a] of shells) { if (a < 0.01) continue; gl.uniform3fv(P.shell.u('uCentre'), c); gl.uniform1f(P.shell.u('uAlpha'), (f.dark ? 0.9 : 0.6) * a); gl.drawElements(gl.TRIANGLES, shell.count, gl.UNSIGNED_INT, 0); }
    gl.bindVertexArray(null); gl.depthMask(true); gl.disable(gl.BLEND);
    drawTree(C);
  };
  stage.drawOverlay = (g, f) => {
    const C = f.C, { off } = poses();
    g.font = '600 13px "Comic Neue", system-ui, sans-serif'; g.textBaseline = 'middle';
    const axis = (u, o, label) => { const a = stage.project(o.map((x, i) => x - 1.35 * u[i])), b = stage.project(o.map((x, i) => x + 1.35 * u[i])); g.strokeStyle = C.muted; g.lineWidth = 1.2; g.setLineDash([5, 5]); g.beginPath(); g.moveTo(a[0], a[1]); g.lineTo(b[0], b[1]); g.stroke(); g.setLineDash([]); g.fillStyle = C.muted; g.textAlign = 'left'; g.fillText(label, b[0] + 6, b[1]); };
    if (st.time < 1.02) { axis(AXIS.a, [0, 0, 0], t('axe de a', 'axis of a')); axis(AXIS.b, [0, 0, 0], t('axe de b', 'axis of b')); }
    const sp = stage.project(st.p), e = stage.project(off.e.map((x, i) => x + st.p[i]));
    g.fillStyle = C.ink; g.strokeStyle = C.surface; g.lineWidth = 4; g.textAlign = 'left';
    const lab = st.time > 1.5 ? t('e : il reste un point', 'e: one point left over') : 'p';
    g.beginPath(); g.arc(e[0], e[1], 7, 0, 2 * Math.PI); g.fillStyle = C.ink; g.fill(); g.lineWidth = 2; g.strokeStyle = C.surface; g.stroke();
    g.lineWidth = 4; g.strokeText(lab, e[0] + 12, e[1] - 10); g.fillStyle = C.ink; g.fillText(lab, e[0] + 12, e[1] - 10);
    if (st.time > 1.05) {
      const s = ease(st.time - 1), label = (o, txt) => { const q = stage.project([o[0], o[1], o[2] - 1.22]); g.globalAlpha = s; g.textAlign = 'center'; g.fillStyle = C.ink; g.fillText(txt, q[0], q[1]); g.globalAlpha = 1; };
      label(off.a, 'S(a) ∪ a·S(A)'); label(off.b, 'S(b) ∪ b·S(B)');
    }
    void sp;
  };
  // ---- Cayley tree of F₂, coloured by piece; after step 1, the two reassembled copies
  function drawTree(C) {
    const g = tree.g, W = tree.W, H = tree.H, depth = Math.min(st.n, 6), col = { e: C.ink, a: C.c[0], A: C.c[1], b: C.c[2], B: C.c[3] };
    g.save(); g.setTransform(tree.scale, 0, 0, tree.scale, 0, 0); g.clearRect(0, 0, W, H); g.fillStyle = C.surface; g.fillRect(0, 0, W, H);
    const dir = { a: [1, 0], A: [-1, 0], b: [0, -1], B: [0, 1] };
    const draw = (cx, cy, L, colourOf) => {
      const rec = (x, y, word, len, k) => {
        for (const s of LETTERS) {
          if (word && word.at(-1) === { a: 'A', A: 'a', b: 'B', B: 'b' }[s]) continue;
          const w = word + s; if (w.length > depth) continue;
          const x2 = x + dir[s][0] * len, y2 = y + dir[s][1] * len;
          g.strokeStyle = colourOf(w); g.lineWidth = Math.max(0.6, 2.4 * 0.62 ** k); g.beginPath(); g.moveTo(x, y); g.lineTo(x2, y2); g.stroke();
          rec(x2, y2, w, len / 2, k + 1);
        }
      };
      rec(cx, cy, '', L, 0); g.fillStyle = C.ink; g.beginPath(); g.arc(cx, cy, 3.5, 0, 2 * Math.PI); g.fill();
    };
    g.font = '600 12px "Comic Neue", system-ui, sans-serif'; g.textAlign = 'center'; g.fillStyle = C.muted;
    if (st.time < 1) {
      draw(W / 2, H / 2 + 6, 52, (w) => col[w[0]]);
      g.fillText(t('Graphe de Cayley de F₂ : chaque branche est une pièce (la première lettre du mot)', 'Cayley graph of F₂: each branch is one piece (the first letter of the word)'), W / 2, 12);
      cap.textContent = t('Le même découpage dans le graphe du groupe : quatre branches de même forme.', 'The same split in the graph of the group: four branches of the same shape.');
    } else {
      // copy 1: S(a) kept, and a·S(A) = all words not starting with a (they keep the colour of S(A)); copy 2 alike with b
      draw(W * 0.26, H / 2 + 6, 44, (w) => w[0] === 'a' ? col.a : col.A);
      draw(W * 0.74, H / 2 + 6, 44, (w) => w[0] === 'b' ? col.b : col.B);
      g.fillText('S(a) ∪ a·S(A)', W * 0.26, 12); g.fillText('S(b) ∪ b·S(B)', W * 0.74, 12);
      cap.textContent = t('Après le mouvement : la branche S(A), tournée par a, devient les trois autres branches ; chaque copie est le graphe entier.', 'After the move: the branch S(A), turned by a, becomes the three other branches; each copy is the whole graph.');
    }
    g.restore();
  }
  tree.redraw = () => stage.wake();
  // ---- drag p
  stage.pick = (ray, e, [x, y]) => {
    if (st.time > 0.02) return null;
    const s = stage.project(st.p); if (Math.hypot(s[0] - x, s[1] - y) > (e.pointerType === 'touch' ? 34 : 20)) return null;
    return { move(r) { const h = raySphere(r.o, r.d, [0, 0, 0], 1); if (h) { st.p = norm3(h); stage.wake(); } } };
  };
  stage.key = (e) => {
    if (e.key === ' ') { toggle(); return true; }
    return false;
  };
  // ---- timeline
  const play = $('#bt-play'), time = $('#bt-time'), timeOut = $('#bt-time-out');
  const setTime = (v) => { st.time = clamp(v, 0, 2); time.value = String(st.time); timeOut.textContent = st.time.toLocaleString(lang, { maximumFractionDigits: 2 }); stage.wake(); };
  const label = () => { play.textContent = st.playing ? t('Pause', 'Pause') : t('Lecture', 'Play'); play.setAttribute('aria-pressed', String(st.playing)); };
  function toggle() {
    if (reduced()) { setTime(st.time < 1 ? 1 : st.time < 2 ? 2 : 0); return; }
    if (!st.playing && st.time >= 2) setTime(0);
    st.playing = !st.playing; label(); stage.wake();
  }
  stage.update = (dt) => { if (!st.playing) return false; setTime(st.time + dt / 3); if (st.time >= 2) { st.playing = false; label(); } return st.playing; };
  stage.restore = () => { pts = null; build(); };
  const abort = new AbortController(), on = (el, ev, fn) => el.addEventListener(ev, fn, { signal: abort.signal });
  on(play, 'click', toggle); on($('#bt-reset'), 'click', () => { st.playing = false; label(); setTime(0); });
  bind(root, 'bt-time', (v) => { st.playing = false; label(); setTime(v); }, (v) => v.toLocaleString(lang, { maximumFractionDigits: 2 }));
  bind(root, 'bt-n', (v) => { st.n = v; upload(); });
  bind(root, 'bt-orbits', (v) => { st.orbits = v; stage.wake(); });
  bind(root, 'bt-size', (v) => { st.size = v; stage.wake(); }, (v) => v.toLocaleString(lang, { maximumFractionDigits: 2 }));
  build(); stage.start();
  return () => { clearTimeout(exactJob); abort.abort(); stage.destroy(); tree.disconnect?.(); fig.remove(); metrics.el.remove(); };
}
